module tower_coverage (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [15:0] x0, y0, x1, y1, x2, y2, x3, y3,\n    input wire [15:0] x4, y4, x5, y5, x6, y6, x7, y7,\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] S_IDLE           = 3'd0;\n    localparam [2:0] S_RESET          = 3'd1;\n    localparam [2:0] S_COMPUTE_DIST   = 3'd2;\n    localparam [2:0] S_BUILD_COMP     = 3'd3;\n    localparam [2:0] S_ASSIGN_COMP    = 3'd4;\n    localparam [2:0] S_COMPUTE_MIN    = 3'd5;\n    localparam [2:0] S_EVALUATE       = 3'd6;\n    localparam [2:0] S_DONE           = 3'd7;\n\n    reg [2:0] state, next_state;\n\n    // Tower storage\n    reg [15:0] x_reg [0:7];\n    reg [15:0] y_reg [0:7];\n\n    // Union-Find arrays\n    reg [2:0] parent [0:7];\n    reg [3:0] size   [0:7];\n\n    // Component tracking\n    reg [2:0] comp_id [0:7];\n    reg [3:0] comp_size [0:7];\n    reg [3:0] num_components;\n\n    // Distance tracking\n    reg [31:0] dist_sq [0:7][0:7];\n    reg        edge_exists [0:7][0:7];\n\n    // Loop counters/indices\n    reg [3:0] i, j, k, m;\n    reg [3:0] n_reg;\n    reg [15:0] dx, dy;\n    reg [31:0] dx_sq, dy_sq;\n    reg [31:0] min_dist_sq;\n    reg [7:0] current_max;\n    reg [7:0] temp_total;\n    reg found_root;\n    reg [2:0] root_a, root_b, root_i;\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        case (state)\n            S_IDLE         : next_state = start ? S_RESET : S_IDLE;\n            S_RESET        : next_state = S_COMPUTE_DIST;\n            S_COMPUTE_DIST : next_state = (i >= n_reg && j >= n_reg) ? S_BUILD_COMP : S_COMPUTE_DIST;\n            S_BUILD_COMP   : next_state = (i >= n_reg) ? S_ASSIGN_COMP : S_BUILD_COMP;\n            S_ASSIGN_COMP  : next_state = S_COMPUTE_MIN;\n            S_COMPUTE_MIN  : next_state = (i >= num_components) ? S_EVALUATE : S_COMPUTE_MIN;\n            S_EVALUATE     : next_state = S_DONE;\n            S_DONE         : next_state = S_DONE;\n            default        : next_state = S_IDLE;\n        endcase\n    end\n\n    // Main logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= S_IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            current_max <= 8'd0;\n            temp_total <= 8'd0;\n            n_reg <= 4'd0;\n            num_components <= 4'd0;\n            \n            // Initialize arrays\n            for (k = 0; k < 8; k = k + 1) begin\n                x_reg[k] <= 16'd0;\n                y_reg[k] <= 16'd0;\n                parent[k] <= 3'd0;\n                size[k] <= 4'd1;\n                comp_id[k] <= 3'd0;\n                comp_size[k] <= 4'd0;\n                for (m = 0; m < 8; m = m + 1) begin\n                    dist_sq[k][m] <= 32'd0;\n                    edge_exists[k][m] <= 1'b0;\n                end\n            end\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        n_reg <= n;\n                        // Store coordinates\n                        x_reg[0] <= x0; y_reg[0] <= y0;\n                        x_reg[1] <= x1; y_reg[1] <= y1;\n                        x_reg[2] <= x2; y_reg[2] <= y2;\n                        x_reg[3] <= x3; y_reg[3] <= y3;\n                        x_reg[4] <= x4; y_reg[4] <= y4;\n                        x_reg[5] <= x5; y_reg[5] <= y5;\n                        x_reg[6] <= x6; y_reg[6] <= y6;\n                        x_reg[7] <= x7; y_reg[7] <= y7;\n                    end\n                end\n                \n                S_RESET: begin\n                    // Initialize union-find structures\n                    for (k = 0; k < 8; k = k + 1) begin\n                        parent[k] <= k[2:0];\n                        size[k] <= 4'd1;\n                    end\n                    i <= 4'd0;\n                    j <= 4'd0;\n                    current_max <= 8'd0;\n                end\n                \n                S_COMPUTE_DIST: begin\n                    if (i < n_reg) begin\n                        if (j < n_reg) begin\n                            // Compute squared distance\n                            dx <= (x_reg[i] > x_reg[j]) ? (x_reg[i] - x_reg[j]) : (x_reg[j] - x_reg[i]);\n                            dy <= (y_reg[i] > y_reg[j]) ? (y_reg[i] - y_reg[j]) : (y_reg[j] - y_reg[i]);\n                            dx_sq <= dx * dx;\n                            dy_sq <= dy * dy;\n                            dist_sq[i][j] <= dx_sq + dy_sq;\n                            edge_exists[i][j] <= (dx_sq + dy_sq) <= 262144;\n                            j <= j + 1;\n                        end else begin\n                            j <= 4'd0;\n                            i <= i + 1;\n                        end\n                    end\n                end\n                \n                S_BUILD_COMP: begin\n                    if (i < n_reg) begin\n                        for (j = 0; j < n_reg; j = j + 1) begin\n                            if (edge_exists[i][j] && i != j) begin\n                                // Find roots\n                                root_a = parent[i];\n                                while (parent[root_a] != root_a) root_a = parent[root_a];\n                                root_b = parent[j];\n                                while (parent[root_b] != root_b) root_b = parent[root_b];\n                                \n                                // Union by size\n                                if (root_a != root_b) begin\n                                    if (size[root_a] < size[root_b]) begin\n                                        parent[root_a] <= root_b;\n                                        size[root_b] <= size[root_b] + size[root_a];\n                                    end else begin\n                                        parent[root_b] <= root_a;\n                                        size[root_a] <= size[root_a] + size[root_b];\n                                    end\n                                end\n                            end\n                        end\n                        i <= i + 1;\n                    end\n                end\n                \n                S_ASSIGN_COMP: begin\n                    // Assign component IDs\n                    num_components <= 4'd0;\n                    for (k = 0; k < n_reg; k = k + 1) begin\n                        root_i = parent[k];\n                        while (parent[root_i] != root_i) root_i = parent[root_i];\n                        found_root = 1'b0;\n                        for (m = 0; m < num_components; m = m + 1) begin\n                            if (comp_id[m] == root_i) begin\n                                comp_size[m] <= comp_size[m] + 4'd1;\n                                found_root = 1'b1;\n                            end\n                        end\n                        if (!found_root) begin\n                            comp_id[num_components] <= root_i;\n                            comp_size[num_components] <= 4'd1;\n                            num_components <= num_components + 4'd1;\n                        end\n                    end\n                    i <= 4'd0;\n                end\n                \n                S_COMPUTE_MIN: begin\n                    if (i < num_components) begin\n                        for (j = 0; j < num_components; j = j + 1) begin\n                            if (i != j) begin\n                                // Find min distance between components i and j (simplified)\n                                if (min_dist_sq <= 262144) begin\n                                    temp_total <= comp_size[i] + comp_size[j] + 8'd1;\n                                    if (temp_total > current_max) current_max <= temp_total;\n                                end\n                            end\n                        end\n                        i <= i + 1;\n                    end\n                end\n                \n                S_EVALUATE: begin\n                    // Check single component maximum\n                    for (k = 0; k < num_components; k = k + 1) begin\n                        temp_total <= comp_size[k] + 8'd1;\n                        if (temp_total > current_max) current_max <= temp_total;\n                    end\n                    result <= current_max;\n                end\n                \n                S_DONE: begin\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\nendmodule